USE askq_university;
DROP TEMPORARY TABLE IF EXISTS cohort_results;
CREATE TEMPORARY TABLE cohort_results (
    check_no INT AUTO_INCREMENT PRIMARY KEY, cohort VARCHAR(20),
    attack_class VARCHAR(20), check_name VARCHAR(70), expected VARCHAR(10),
    actual DECIMAL(12,2), result CHAR(4));

-- C1 ASTRO students (whole group)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C1_DIFFERENCING', 'DIFFERENCING', 'C1 ASTRO students (whole group)', '>= 15', q.n, CASE WHEN q.n >= 15 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'ASTRO') AS n) q;
-- C1 ASTRO domestic students (complement)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C1_DIFFERENCING', 'DIFFERENCING', 'C1 ASTRO domestic students (complement)', '>= 15', q.n, CASE WHEN q.n >= 15 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'ASTRO' AND s.residency_status = 'DOMESTIC') AS n) q;
-- C1 ASTRO international students (target)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C1_DIFFERENCING', 'DIFFERENCING', 'C1 ASTRO international students (target)', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'ASTRO' AND s.residency_status = 'INTERNATIONAL') AS n) q;
-- C1 target has Spring 2026 grades
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C1_DIFFERENCING', 'DIFFERENCING', 'C1 target has Spring 2026 grades', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(DISTINCT s.student_id) FROM students s JOIN departments d ON d.department_id = s.department_id JOIN enrollments e ON e.student_id = s.student_id JOIN grades g ON g.enrollment_id = e.enrollment_id WHERE d.department_code = 'ASTRO' AND s.residency_status = 'INTERNATIONAL') AS n) q;
-- C1 target average differs from complement by >= 5
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C1_DIFFERENCING', 'DIFFERENCING', 'C1 target average differs from complement by >= 5', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT CASE WHEN ABS(t.m - c.m) >= 5 THEN 1 ELSE 0 END FROM (SELECT AVG(g.marks) AS m FROM students s JOIN departments d ON d.department_id = s.department_id JOIN enrollments e ON e.student_id = s.student_id JOIN grades g ON g.enrollment_id = e.enrollment_id WHERE d.department_code = 'ASTRO' AND s.residency_status = 'INTERNATIONAL') t CROSS JOIN (SELECT AVG(g.marks) AS m FROM students s JOIN departments d ON d.department_id = s.department_id JOIN enrollments e ON e.student_id = s.student_id JOIN grades g ON g.enrollment_id = e.enrollment_id WHERE d.department_code = 'ASTRO' AND s.residency_status = 'DOMESTIC') c) AS n) q;
