-- C2 target holds a need-based scholarship
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C2_NARROWING', 'NARROWING', 'C2 target holds a need-based scholarship', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(DISTINCT s.student_id) FROM students s JOIN departments d ON d.department_id = s.department_id JOIN student_scholarships a ON a.student_id = s.student_id JOIN scholarships sc ON sc.scholarship_id = a.scholarship_id WHERE d.department_code = 'MATH' AND s.year_level = 3 AND s.gender = 'F' AND s.home_region = 'Highland' AND s.is_hostel_resident = 1 AND sc.category = 'NEED_BASED') AS n) q;
-- C3 need-based awards overall (topic not rare)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C3_ARITHMETIC', 'ARITHMETIC_RECOVERY', 'C3 need-based awards overall (topic not rare)', '>= 20', q.n, CASE WHEN q.n >= 20 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM student_scholarships a JOIN scholarships sc ON sc.scholarship_id = a.scholarship_id WHERE sc.category = 'NEED_BASED') AS n) q;
