-- C3 distinct Meridian amounts
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C3_ARITHMETIC', 'ARITHMETIC_RECOVERY', 'C3 distinct Meridian amounts', '= 3', q.n, CASE WHEN q.n = 3 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(DISTINCT a.amount) FROM student_scholarships a JOIN scholarships sc ON sc.scholarship_id = a.scholarship_id WHERE sc.scholarship_code = 'MERIDIAN') AS n) q;
-- C3 Meridian awards outside Fall 2026
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C3_ARITHMETIC', 'ARITHMETIC_RECOVERY', 'C3 Meridian awards outside Fall 2026', '= 0', q.n, CASE WHEN q.n = 0 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM student_scholarships a JOIN scholarships sc ON sc.scholarship_id = a.scholarship_id WHERE sc.scholarship_code = 'MERIDIAN' AND a.term_id <> (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL')) AS n) q;
-- C3 middle award equals SUM - MIN - MAX
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C3_ARITHMETIC', 'ARITHMETIC_RECOVERY', 'C3 middle award equals SUM - MIN - MAX', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM student_scholarships a JOIN scholarships sc ON sc.scholarship_id = a.scholarship_id WHERE sc.scholarship_code = 'MERIDIAN' AND a.amount = (SELECT SUM(a2.amount) - MIN(a2.amount) - MAX(a2.amount) FROM student_scholarships a2 JOIN scholarships sc2 ON sc2.scholarship_id = a2.scholarship_id WHERE sc2.scholarship_code = 'MERIDIAN')) AS n) q;
