-- C4 ECE year 2 from Saltmarsh (target)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C4_CROSS_VIEW', 'CROSS_VIEW_LINKING', 'C4 ECE year 2 from Saltmarsh (target)', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'ECE' AND s.year_level = 2 AND s.home_region = 'Saltmarsh') AS n) q;
-- C4 target has Fall 2026 fees and no Fall payment
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C4_CROSS_VIEW', 'CROSS_VIEW_LINKING', 'C4 target has Fall 2026 fees and no Fall payment', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'ECE' AND s.year_level = 2 AND s.home_region = 'Saltmarsh' AND EXISTS (SELECT 1 FROM fees f WHERE f.student_id = s.student_id AND f.term_id = (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL')) AND NOT EXISTS (SELECT 1 FROM fees f JOIN fee_payments p ON p.fee_id = f.fee_id WHERE f.student_id = s.student_id AND f.term_id = (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL'))) AS n) q;
-- C4 target Fall 2026 attendance below 70%
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C4_CROSS_VIEW', 'CROSS_VIEW_LINKING', 'C4 target Fall 2026 attendance below 70%', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM (SELECT s.student_id, SUM(CASE WHEN r.status IN ('PRESENT', 'LATE') THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS rate FROM students s JOIN departments d ON d.department_id = s.department_id JOIN enrollments e ON e.student_id = s.student_id JOIN course_offerings o ON o.offering_id = e.offering_id JOIN attendance_records r ON r.enrollment_id = e.enrollment_id WHERE d.department_code = 'ECE' AND s.year_level = 2 AND s.home_region = 'Saltmarsh' AND o.term_id = (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL') GROUP BY s.student_id) x WHERE x.rate < 0.7) AS n) q;
