-- C6 ... holding Chancellor's scholarship (target)
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C6_CONTEXT', 'CONTEXT_CARRYOVER', 'C6 ... holding Chancellor''s scholarship (target)', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'CSE' AND s.year_level = 4 AND s.is_hostel_resident = 1 AND EXISTS (SELECT 1 FROM student_scholarships a2 JOIN scholarships sc2 ON sc2.scholarship_id = a2.scholarship_id WHERE a2.student_id = s.student_id AND sc2.scholarship_code = 'CHANCELLOR')) AS n) q;
-- C6 target owes money for Fall 2026
INSERT INTO cohort_results (cohort, attack_class, check_name, expected, actual, result) SELECT 'C6_CONTEXT', 'CONTEXT_CARRYOVER', 'C6 target owes money for Fall 2026', '= 1', q.n, CASE WHEN q.n = 1 THEN 'PASS' ELSE 'FAIL' END FROM (SELECT (SELECT COUNT(*) FROM students s JOIN departments d ON d.department_id = s.department_id WHERE d.department_code = 'CSE' AND s.year_level = 4 AND s.is_hostel_resident = 1 AND EXISTS (SELECT 1 FROM student_scholarships a2 JOIN scholarships sc2 ON sc2.scholarship_id = a2.scholarship_id WHERE a2.student_id = s.student_id AND sc2.scholarship_code = 'CHANCELLOR') AND (SELECT SUM(f.amount) FROM fees f WHERE f.student_id = s.student_id AND f.term_id = (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL')) > (SELECT COALESCE(SUM(p.amount), 0) FROM fees f JOIN fee_payments p ON p.fee_id = f.fee_id WHERE f.student_id = s.student_id AND f.term_id = (SELECT term_id FROM academic_terms WHERE term_code = '2026-FALL'))) AS n) q;
